#[test]
fn learned_lengthscales_detect_irrelevant_dimension() {
    let mut xs = Vec::new();
    let mut ys = Vec::new();
    for i in 0..5 {
        for j in 0..5 {
            let x0 = i as f64 / 4.0;
            let x1 = j as f64 / 4.0;
            xs.push(Array1::from(vec![x0, x1]));
            ys.push((x0 - 0.35).powi(2));
        }
    }
    let learned = learn_lengthscales(&xs, &ys, &[0.25, 0.25], 1.0, 1e-8).unwrap();
    assert!(
        learned[1] > learned[0],
        "irrelevant dimension should get longer lengthscale: {learned:?}"
    );
}

#[test]
fn gp_prediction_reports_latent_not_observation_variance() {
    let xs = vec![Array1::from(vec![0.0]), Array1::from(vec![1.0])];
    let ys = vec![0.0, 1.0];
    let gp = GaussianProcess::fit(&xs, &ys, &[0.4], 1.0, 1e-2).unwrap();
    let (_, std) = gp.predict(&Array1::from(vec![0.0]));
    assert!(
        std < 0.08,
        "latent posterior std should not include observation noise: {std}"
    );
}

#[test]
fn qei_batch_value_includes_joint_improvement() {
    let xs = vec![Array1::from(vec![0.0]), Array1::from(vec![1.0])];
    let ys = vec![0.0, 1.0];
    let gp = GaussianProcess::fit(&xs, &ys, &[0.5], 1.0, 1e-8).unwrap();
    let batch = vec![Array1::from(vec![0.25]), Array1::from(vec![0.75])];
    let normals = vec![vec![0.0, 0.0], vec![-1.0, 1.0], vec![1.0, -1.0]];
    let score = q_expected_improvement_mc(&gp, &batch, 0.5, 0.0, &normals);
    assert!(score.is_finite() && score > 0.0);
}

#[test]
fn bayes_opt_converges_on_quadratic() {
    let f = |x: &Array1<f64>| -> f64 { (x[0] - 0.25).powi(2) + (x[1] + 0.5).powi(2) };
    let cfg = BayesOptConfig {
        bounds: vec![(-1.0, 1.0), (-1.0, 1.0)],
        maxeval: 60,
        initial_samples: 8,
        batch_size: 2,
        candidate_pool_size: 128,
        seed: Some(7),
        ..Default::default()
    };
    let report = bayesian_optimization(&f, cfg).unwrap();
    assert!(report.fun < 0.05, "fun={}", report.fun);
}

#[test]
fn multi_objective_returns_non_dominated_front() {
    let f = |x: &Array1<f64>| -> Vec<f64> { vec![x[0].powi(2), (x[0] - 1.0).powi(2)] };
    let cfg = BayesOptConfig {
        bounds: vec![(0.0, 1.0)],
        maxeval: 20,
        initial_samples: 6,
        batch_size: 2,
        candidate_pool_size: 64,
        seed: Some(3),
        ..Default::default()
    };
    let report = bayesian_multi_objective(&f, cfg).unwrap();
    assert!(!report.pareto_front.is_empty());
}

#[test]
fn is_new_point_scales_with_dimension() {
    // In 1D the old fixed threshold 1e-18 (distance 1e-9) is too lax:
    // points 1e-7 apart have squared distance 1e-14 > 1e-18, so they are
    // wrongly admitted as distinct. A dimension-scaled threshold catches
    // more duplicates in low dimensions.
    let bounds_1d = vec![(0.0, 1.0)];
    let q1 = Array1::from_vec(vec![0.5]);
    let q2 = Array1::from_vec(vec![0.5 + 1e-7]);
    assert!(
        !is_new_point(
            &normalize(&q2, &bounds_1d),
            &[normalize(&q1, &bounds_1d)],
            &[],
            &bounds_1d
        ),
        "points 1e-7 apart in 1D should be treated as duplicates"
    );

    // In high dimensions the old threshold is too strict relative to the
    // natural scale of the space. With a scaled threshold, points that
    // differ by a small but meaningful amount in every coordinate are
    // still accepted as distinct.
    let bounds_100d = vec![(0.0, 1.0); 100];
    let p1 = Array1::from_vec(vec![0.5; 100]);
    let mut p2 = p1.clone();
    for i in 0..100 {
        p2[i] += 1e-8; // small but clear perturbation
    }
    assert!(
        is_new_point(
            &normalize(&p2, &bounds_100d),
            &[normalize(&p1, &bounds_100d)],
            &[],
            &bounds_100d
        ),
        "points differing by 1e-8 in every coordinate should be distinct in 100D"
    );

    // Exact duplicates must still be rejected regardless of dimension.
    let r1 = Array1::from_vec(vec![0.3; 50]);
    let r2 = r1.clone();
    assert!(
        !is_new_point(
            &normalize(&r2, &bounds_100d),
            &[normalize(&r1, &bounds_100d)],
            &[],
            &bounds_100d
        ),
        "exact duplicates should be rejected in 50D"
    );
}

#[test]
fn test_matern52_zero_distance_equals_variance() {
    let a = Array1::from_vec(vec![1.0, 2.0]);
    let b = a.clone();
    let k = matern52(&a, &b, &[1.0, 1.0], 2.5);
    assert!((k - 2.5).abs() < 1e-12);
}

#[test]
fn test_matern52_decreases_with_distance() {
    let a = Array1::zeros(1);
    let close = Array1::from_vec(vec![0.1]);
    let far = Array1::from_vec(vec![2.0]);
    let k_close = matern52(&a, &close, &[1.0], 1.0);
    let k_far = matern52(&a, &far, &[1.0], 1.0);
    assert!(k_close > k_far);
}

#[test]
fn test_kernel_matrix_is_symmetric() {
    let xs = vec![Array1::from_vec(vec![0.0]), Array1::from_vec(vec![1.0])];
    let k = kernel_matrix(&xs, &[1.0], 1.0);
    assert_eq!(k.nrows(), 2);
    assert_eq!(k.ncols(), 2);
    assert!((k[(0, 1)] - k[(1, 0)]).abs() < 1e-12);
}

#[test]
fn test_clip_to_bounds_and_denormalize() {
    let x = Array1::from_vec(vec![-0.5, 1.5, 0.5]);
    let bounds = vec![(0.0, 1.0), (0.0, 1.0), (0.0, 10.0)];
    let clipped = clip_to_bounds(&x, &bounds);
    assert!((clipped[0] - 0.0).abs() < 1e-12);
    assert!((clipped[1] - 1.0).abs() < 1e-12);
    assert!((clipped[2] - 0.5).abs() < 1e-12);

    let back = denormalize(&clipped, &bounds);
    assert!((back[0] - 0.0).abs() < 1e-12);
    assert!((back[1] - 1.0).abs() < 1e-12);
    assert!((back[2] - 5.0).abs() < 1e-12);
}

#[test]
fn test_dominates_or_equal_and_reference_point() {
    assert!(dominates_or_equal(&[1.0, 2.0], &[1.0, 3.0]));
    assert!(dominates_or_equal(&[1.0, 2.0], &[1.0, 2.0]));
    assert!(!dominates_or_equal(&[2.0, 2.0], &[1.0, 2.0]));

    let values = vec![vec![0.0, 1.0], vec![1.0, 0.0]];
    let rp = reference_point(&values);
    assert!(rp[0] > 1.0 && rp[1] > 1.0);
}

#[test]
fn test_solve_triangular_systems() {
    let l = DMatrix::from_row_slice(2, 2, &[1.0, 0.0, 2.0, 3.0]);
    let b = DVector::from_vec(vec![1.0, 8.0]);
    let x = solve_lower(&l, &b);
    assert!((x[0] - 1.0).abs() < 1e-12);
    assert!((x[1] - 2.0).abs() < 1e-12);

    // L^T x = [5, 6]  =>  x1 = 6/3 = 2, x0 = 5 - 2*2 = 1
    let b2 = DVector::from_vec(vec![5.0, 6.0]);
    let x2 = solve_upper_from_lower(&l, &b2);
    assert!((x2[0] - 1.0).abs() < 1e-12);
    assert!((x2[1] - 2.0).abs() < 1e-12);
}

#[test]
fn test_cholesky_lower_and_solve() {
    let a = DMatrix::from_row_slice(2, 2, &[4.0, 0.0, 0.0, 9.0]);
    let l = cholesky_lower(&a).unwrap();
    assert!((l[(0, 0)] - 2.0).abs() < 1e-12);
    assert!((l[(1, 1)] - 3.0).abs() < 1e-12);
    assert!(l[(0, 1)].abs() < 1e-12);
    assert!(l[(1, 0)].abs() < 1e-12);

    let b = DVector::from_vec(vec![4.0, 18.0]);
    let x = cholesky_solve(&l, &b);
    assert!((x[0] - 1.0).abs() < 1e-9);
    assert!((x[1] - 2.0).abs() < 1e-9);
}

#[test]
fn test_normal_pdf_and_cdf() {
    let p0 = normal_pdf(0.0);
    let p1 = normal_pdf(1.0);
    assert!(p0 > p1);
    assert!(p0 > 0.0);

    assert!((normal_cdf(0.0) - 0.5).abs() < 1e-6);
    assert!((normal_cdf(1.0) + normal_cdf(-1.0) - 1.0).abs() < 1e-6);
}
